import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Button from "../../ui/shadcn-button";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((_model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("flex flex-col items-start gap-2")],
    [
      h.a([h.Href("/login"), h.Class(Button.shadcnButtonClassName)], ["Login"]),
      h.span(
        [h.Class("text-sm text-gray-600")],
        ["Rendered as an anchor with the shadcn button class."]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Button As Child example", () => {
  test("renders the As Child anchor without a click handler", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("link", { name: "Login" })).toExist(),
      Scene.expect(
        Scene.text("Rendered as an anchor with the shadcn button class.")
      ).toExist(),
      Scene.expect(Scene.role("link", { name: "Login" })).toHaveAttr(
        "href",
        "/login"
      ),
      Scene.expect(Scene.role("link", { name: "Login" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
